@startuml

class Customer {
  + name : string
  + phone_number : string
}

class Table {
  + number_of_seats : int
  + is_smoking : boolean
}

class Reservation {
  + day : date
  + time : time
  + number_of_people : int
}

class Waiter {
  + name : string
  + years_of_service : int
}

class Bill {
  + total_amount : double
}

class Dish {
  + name : string
  + unit_price : double
}

class BillItem {
  + quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "*" -- "1..*" Table : assigned to
Waiter "1" -- "*" Table : serves
Customer "1" -- "*" Bill : receives
Bill "1" *-- "*" BillItem : contains
BillItem "*" -- "1" Dish : includes

@enduml

